//! 🎚️ Typed record and enum cursors birth only their currently visited original field.
use super::*;
/// 🧬️ Direct tag, field metadata and field projection operations are bounded, nonallocating and nontraversing within their declared work.
pub trait RetainedEqualityFields:RetainedEquality{
 const SHAPE_WORK:u64;const FIELD_METADATA_WORK:u64;const FIELD_PROJECTION_WORK:u64;
 fn equality_field_birth_work(left:&Self,index:usize)->Result<Option<u64>,ValueError>;
 fn equality_shape(left:&Self,right:&Self)->Option<usize>;
 fn equality_field_inline_bytes(left:&Self,index:usize)->Option<usize>;
 fn equality_field_inline_work(left:&Self,index:usize)->Option<u64>;
 fn equality_field_inline(left:&Self,right:&Self,index:usize)->Option<bool>;
 fn equality_field_bytes(left:&Self,index:usize)->usize;
 fn equality_field(left:&Self,index:usize,work:u64,grant:RetainedCloneGrant,actual:&mut Option<usize>)->crate::RetainedWorkOutcome<Option<(Box<dyn RetainedEqualityCursor<Self>>,RetainedCloneProgress)>>;
}
/// 🚶️ One funded field body and its genuine child frontier remain live until child-first closure.
#[derive(Clone,Copy)]struct RecordHeader{shape:Option<usize>,inline_bytes:Option<usize>,inline_work:Option<u64>,field_bytes:usize,birth_work:u64}
pub struct RetainedRecordEquality<T:RetainedEqualityFields>{index:usize,active:Option<Box<dyn RetainedEqualityCursor<T>>>,bytes:usize,pending:Option<bool>,result:Option<bool>,header:Option<RecordHeader>,closing:bool}
impl<T:RetainedEqualityFields> RetainedRecordEquality<T>{
 pub fn new()->Self{Self{index:0,active:None,bytes:0,pending:None,result:None,header:None,closing:false}}
 fn fixed()->usize{0}
}
impl<T:RetainedEqualityFields> RetainedEqualityCursor<T> for RetainedRecordEquality<T>{
 fn demand(&self,body:usize,work:u64)->Result<RetirementDemand,ValueError>{
  if self.closing||self.result.is_some(){return Err(invalid("typed record comparison is closing or settled"))}if self.header.is_none(){return Ok(scalar(size_of::<Option<RecordHeader>>()*2))}let h=self.header.ok_or_else(||invalid("record header absent"))?;
  if h.shape.is_none()||h.shape==Some(self.index){return Ok(scalar(size_of::<Option<bool>>()*2))}
  if let Some(active)=self.active.as_ref(){if self.pending.is_some(){if active.terminal_is_empty(){return Ok(RetirementDemand{release_bytes:self.bytes,..scalar(size_of::<Option<RecordHeader>>()*2+size_of::<Option<Box<dyn RetainedEqualityCursor<T>>>>()*2+size_of::<usize>()*4+size_of::<Option<bool>>()*4)})}let mut d=active.close_demand(body)?;d.depth+=1;return Ok(d)}let mut d=active.demand_admitted(body,work.saturating_sub(3))?;d.copy_bytes+=size_of::<Option<bool>>()*2;d.depth+=1;return Ok(d)}
  if let Some(width)=h.inline_bytes{return Ok(scalar(width+size_of::<Option<RecordHeader>>()*2+size_of::<usize>()*2+size_of::<Option<bool>>()*2))}
  Ok(RetirementDemand{copy_bytes:h.field_bytes.checked_mul(2).and_then(|n|n.checked_add(size_of::<Option<Box<dyn RetainedEqualityCursor<T>>>>()*2+size_of::<usize>()*2)).ok_or_else(||invalid("record field copy overflow"))?,capacity_bytes:h.field_bytes,depth:1,..Default::default()})
 }
 fn demand_admitted(&self,body:usize,work:u64)->Result<RetirementDemand,ValueError>{self.demand(body,work)}
 fn work_demand(&self,body:usize,work:u64)->Result<u64,ValueError>{
  if self.closing||self.result.is_some(){return Err(invalid("typed record comparison is closing or settled"))}let required=if let Some(h)=self.header{if h.shape.is_none()||h.shape==Some(self.index){1}else if let Some(active)=self.active.as_ref(){if self.pending.is_some(){if active.terminal_is_empty(){6}else{active.close_work_demand(body)?.checked_add(1).ok_or_else(||invalid("record work overflow"))?}}else{let child=active.work_demand(body,work.saturating_sub(3))?;if child==0{return Ok(0)}child.checked_add(3).ok_or_else(||invalid("record work overflow"))?}}else if h.inline_bytes.is_some(){h.inline_work.ok_or_else(||invalid("typed inline field work absent"))?.checked_add(T::FIELD_PROJECTION_WORK.checked_mul(2).ok_or_else(||invalid("record projection overflow"))?).and_then(|v|v.checked_add(3)).ok_or_else(||invalid("record work overflow"))?}else{T::FIELD_PROJECTION_WORK.checked_add(h.birth_work).and_then(|v|v.checked_add(2)).ok_or_else(||invalid("record work overflow"))?}}else{T::SHAPE_WORK.checked_add(T::FIELD_METADATA_WORK.checked_mul(3).ok_or_else(||invalid("record metadata overflow"))?).and_then(|v|v.checked_add(1)).ok_or_else(||invalid("record inspection overflow"))?};Ok(if required<=work{required}else{0})
 }
 fn advance(&mut self,l:&T,r:&T,body:usize,maximum_work_units:u64,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<RetainedEqualityStep,crate::OriginalRetirementFailure>{let g=effect.grant();let mut work:u128=0;let result:Result<_,crate::OriginalRetirementFailure>=(||{
  if effect.actual().is_some(){return Err(invalid("equality advance needs an empty allocation marker").into())}if self.closing{return Err(invalid("typed comparison is closing").into())}if self.result.is_some(){return Ok(RetainedEqualityStep{equal:self.result,progress:Default::default()})}if self.work_demand(body,maximum_work_units)?==0{return Ok(RetainedEqualityStep{equal:None,progress:Default::default()})}let d=self.demand_admitted(body,maximum_work_units)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedEqualityStep{equal:None,progress:Default::default()})}
  if self.header.is_none(){let shape=T::equality_shape(l,r);work=u128::from(T::SHAPE_WORK);let(mut inline_bytes,mut inline_work,mut field_bytes,mut birth_work)=(None,None,0,0);if shape.is_some_and(|count|self.index<count){inline_bytes=T::equality_field_inline_bytes(l,self.index);work+=u128::from(T::FIELD_METADATA_WORK);if inline_bytes.is_some(){inline_work=T::equality_field_inline_work(l,self.index).filter(|value|*value>0);work+=u128::from(T::FIELD_METADATA_WORK);if inline_work.is_none(){return Err(invalid("typed inline field work absent").into())}}else{field_bytes=T::equality_field_bytes(l,self.index);work+=u128::from(T::FIELD_METADATA_WORK);birth_work=T::equality_field_birth_work(l,self.index)?.ok_or_else(||invalid("typed field birth work absent"))?;work+=u128::from(T::FIELD_METADATA_WORK)}}else if shape.is_some_and(|count|self.index>count){return Err(invalid("typed record index exceeds shape").into())}self.header=Some(RecordHeader{shape,inline_bytes,inline_work,field_bytes,birth_work});work+=1;return Ok(RetainedEqualityStep{equal:None,progress:RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}})}
  let h=self.header.ok_or_else(||invalid("record header absent"))?;let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};
  if h.shape.is_none(){self.result=Some(false);work=1}else if h.shape==Some(self.index){self.result=Some(true);work=1}else if self.active.is_none()&&h.inline_bytes.is_some(){let equal=T::equality_field_inline(l,r,self.index).ok_or_else(||invalid("typed record inline field omitted equality"))?;work=u128::from(h.inline_work.ok_or_else(||invalid("typed inline work absent"))?+T::FIELD_PROJECTION_WORK*2+3);self.index+=1;self.result=if !equal{Some(false)}else if h.shape==Some(self.index){Some(true)}else{None};self.header=None}
  else if self.active.is_none(){let turn=T::equality_field(l,self.index,maximum_work_units-T::FIELD_PROJECTION_WORK-2,g,effect.actual());work=u128::from(T::FIELD_PROJECTION_WORK)+turn.work;let Some((child,receipt))=turn.result? else{return Ok(RetainedEqualityStep{equal:None,progress:Default::default()})};self.active=Some(child);let reported=receipt.retained_capacity_bytes;self.bytes=effect.actual().unwrap_or(0);work+=2;p=receipt;p.retained_capacity_bytes=self.bytes;p.copied_bytes+=d.copy_bytes;let expected=if reported==0{None}else{Some(reported)};if *effect.actual()!=expected||reported!=h.field_bytes{return Err(crate::OriginalRetirementFailure::from_primary(invalid("record field allocation marker disagrees")).with_retained_progress(p))}}
  else if self.pending.is_none(){let extra=size_of::<Option<bool>>()*2;let child_work=maximum_work_units.checked_sub(3).ok_or_else(||invalid("record equality child work underflows"))?;let turn=self.active.as_mut().ok_or_else(||invalid("active absent"))?.advance(l,r,body,child_work,&mut effect.nested_within(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.checked_sub(extra).ok_or_else(||invalid("record equality child copy budget underflows"))?,maximum_depth:g.maximum_depth.checked_sub(1).ok_or_else(||invalid("record equality child depth underflows"))?,..g},child_work));work=1+turn.work;let step=turn.result?;p=step.progress;if let Some(equal)=step.equal{self.pending=Some(equal);p.copied_bytes+=extra;work+=2;self.active.as_mut().ok_or_else(||invalid("active absent"))?.begin_close()}}
  else if !self.active.as_ref().ok_or_else(||invalid("active absent"))?.terminal_is_empty(){let turn=self.active.as_mut().ok_or_else(||invalid("active absent"))?.close_step(&mut effect.nested(RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g}));let turn=complete(turn)?;work=1+turn.work;p=turn.result?.progress()}
  else{drop(self.active.take());work=6;p.released_bytes=self.bytes;self.bytes=0;let equal=self.pending.take().ok_or_else(||invalid("pending absent"))?;self.index+=1;self.result=if !equal{Some(false)}else if h.shape==Some(self.index){Some(true)}else{None};self.header=None}
  Ok(RetainedEqualityStep{equal:self.result,progress:p})})();crate::retained_equality::settle_work(effect,crate::RetainedWorkOutcome{result,work})}
 fn begin_close(&mut self){self.closing=true;if let Some(active)=self.active.as_mut(){active.begin_close();}}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid("typed record close has not begun"))}if let Some(active)=self.active.as_ref(){if !active.terminal_is_empty(){let mut d=active.close_demand(body)?;d.depth+=1;return Ok(d)}return Ok(RetirementDemand{release_bytes:self.bytes,..scalar(size_of::<Option<Box<dyn RetainedEqualityCursor<T>>>>()*2+size_of::<usize>()*2)})}if self.header.is_some(){return Ok(scalar(size_of::<Option<RecordHeader>>()*2))}if self.index!=0||self.bytes!=0||self.pending.is_some()||self.result.is_some(){return Ok(scalar(size_of::<usize>()*4+size_of::<Option<bool>>()*4))}Ok(Default::default())}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid("typed record close has not begun"))}if let Some(active)=self.active.as_ref(){if !active.terminal_is_empty(){return active.close_work_demand(body)?.checked_add(1).ok_or_else(||invalid("record close work overflow"))}return Ok(2)}if self.header.is_some(){return Ok(1)}if self.index!=0||self.bytes!=0||self.pending.is_some()||self.result.is_some(){return Ok(4)}Ok(0)}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{let g=effect.grant();let mut work:u128=0;let result=(||->Result<RetainedCloneStep,RetirementPollExit>{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(active)=self.active.as_mut(){if !active.terminal_is_empty(){let turn=RetirementPollExit::settled(active.close_step(&mut effect.nested(RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g})))?;work=turn.work+1;return Ok(RetainedCloneStep::Progress(turn.result?.progress()))}drop(self.active.take());self.bytes=0;work=2;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}if self.header.is_some(){self.header=None;work=1;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}self.index=0;self.bytes=0;self.pending=None;self.result=None;work=4;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})();crate::retained_equality::settle_poll(effect,RetirementPollExit::finish(result,work))}
 fn terminal_is_empty(&self)->bool{self.active.is_none()&&self.header.is_none()&&self.index==0&&self.bytes==0&&self.pending.is_none()&&self.result.is_none()}
}
impl<T:RetainedEqualityFields> Drop for RetainedRecordEquality<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"typed record retains original field or header")}}
